SELECT TABLE_NAME, COLUMN_NAME, COLUMN_TYPE, IS_NULLABLE, COLUMN_KEY, COLUMN_DEFAULT, EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('CANAIS','VIDEOS','TRECHOS','TEMAS','VIDEO_TEMAS','PLAYLISTS','PLAYLIST_VIDEOS','AVISOS','CONFIG','PRATICAS','MENTOR_REGRAS','LOTES','LIVRO_CAPITULOS') ORDER BY TABLE_NAME, ORDINAL_POSITION